CustomField.formula:
/* 1. Base Points (40 pts max) */
40 +

/* 2. Mileage (40 pts max / 120k anchor) */
(40 * (1 - (Mileage__c / 120000))) +

/* 3. Vehicle Year (10 pts max / 1-pt step) */
CASE(Year__c,
  "2026", 10,
  "2025", 9,
  "2024", 8,
  "2023", 7,
  "2022", 6,
  "2021", 5,
  "2020", 4,
  0
) +

/* 4. Owners (10 pts max / 2-pt step) */
CASE(Previous_Owners__c,
  1, 10,
  2, 8,
  3, 6,
  4
) +

/* 5. Logistics Branching (Math-based logic) */
IF(
  Shipping_Cost__c > 0,
  10,
  IF(
    Logistics__c <= 0,
    0,
    15 * (1 - (Logistics__c / 1200))
  )
) +

/* 6. Price Adjustment (-30 scale on total landed price vs $18000 baseline) */
(-30 * (((Car_Price__c + Shipping_Cost__c) - 18000) / 5000)) +

/* 7. CA Tax Penalty (-2.0 pts flat ONLY if Drive Path in CA) */
IF(
  CONTAINS(UPPER(Location__c), "CA") && (Shipping_Cost__c <= 0),
  -2.0,
  0
)
